                                  '    private(set) var returnedCount = 0\n'
                                  '    private(set) var returnedAccountID: Int?\n'
                                  '    private(set) var returnedMemberID: Int?\n'
                                  '    private struct PendingProfile {\n'
                                  '        let response: SocialPublicProfile\n'
                                  '        let continuation: CheckedContinuation<SocialPublicProfile, '
                                  'Never>\n'
                                  '    }\n'
                                  '    private var pending: [UUID: PendingProfile] = [:]\n'
                                  '    var pendingCount: Int { pending.count }\n'
                                  '    private let fallback = SocialAccountFixtureReader(.content)\n'
                                  '    init(holdsProfileResponses: Bool) { self.holdsProfileResponses = '
                                  'holdsProfileResponses }\n'
                                  '    func publicProfile(memberID: Int) async throws -> SocialPublicProfile '
                                  '{\n'
                                  '        guard holdsProfileResponses else {\n'
                                  '            fallback.identity = identity\n'
                                  '            return try await fallback.publicProfile(memberID: memberID)\n'
                                  '        }\n'
                                  '        let captured = identity, requestID = UUID()\n'
                                  '        let bytes = try JSONSerialization.data(withJSONObject: ["id": '
                                  'memberID,\n'
                                  '            "nickname": "Held profile from account \\(captured.accountID '
                                  '?? 0)"])\n'
                                  '        let response = try JSONDecoder().decode(SocialPublicProfile.self, '
                                  'from: bytes)\n'
                                  '        startedCount += 1\n'
                                  '        let released = await withCheckedContinuation { (continuation: '
                                  'CheckedContinuation<SocialPublicProfile, Never>) in\n'
                                  '            pending[requestID] = .init(response: response, continuation: '
