                                  '\n'
                                  '    init(model: TemplateAuthoringModel) {\n'
                                  '        self.model = model; session = model.coordinator.session\n'
                                  '        identity = model.coordinator.identity; modelGeneration = '
                                  'model.metadataGeneration\n'
                                  '        originalDraft = model.draft\n'
                                  '    }\n'
                                  '    var canRead: Bool {\n'
                                  '        active && model.canReadMetadataDraft && session != nil && session '
                                  '== model.coordinator.session &&\n'
                                  '        identity == model.coordinator.identity && modelGeneration == '
                                  'model.metadataGeneration &&\n'
                                  '        originalDraft == model.draft &&\n'
                                  '        originalDraft.usageLocation.map({ Data($0.utf8) }) == '
                                  'model.draft.usageLocation.map({ Data($0.utf8) })\n'
                                  '    }\n'
                                  '    var canEdit: Bool { canRead && model.canEdit && !model.busy && '
                                  'model.coordinator.review == nil && model.draft.id == nil }\n'
                                  '    var savedRawValue: String? { canRead ? originalDraft.usageLocation : '
                                  'nil }\n'
                                  '    var selected: TemplateVenuePreset? { '
                                  'savedRawValue.flatMap(TemplateVenuePreset.init(storedValue:)) }\n'
                                  '    var hasHistoricalValue: Bool { savedRawValue?.isEmpty == false && '
                                  'selected == nil }\n'
                                  '    func close() { active = false }\n'
                                  '    @discardableResult func select(_ preset: TemplateVenuePreset) -> Bool '
                                  '{\n'
                                  '        guard canEdit else { return false }\n'
                                  '        // Tapping the current choice dismisses without normalizing or '
                                  'saving anything.\n'
                                  '        if selected != preset {\n'
                                  '            model.draft.usageLocation = preset.storedValue\n'
                                  '            model.changed()\n'
                                  '        }\n'
                                  '        close(); return true\n'
                                  '    }\n'
                                  '}\n'
                                  '\n'
                                  '@MainActor struct TemplateAuthoringVenueField: View {\n'
                                  '    private struct Presentation: Identifiable { let id = UUID() }\n'
                                  '    @ObservedObject var model: TemplateAuthoringModel\n'
                                  '    @State private var presented: Presentation?\n'
                                  '    var body: some View {\n'
                                  '        VStack(alignment: .leading, spacing: 4) {\n'
                                  '            Button { presented = Presentation() } label: {\n'
                                  '                LabeledContent {\n'
                                  '                    if model.canReadMetadataDraft, let raw = '
                                  'model.draft.usageLocation, !raw.isEmpty {\n'
                                  '                        if let preset = TemplateVenuePreset(storedValue: '
                                  'raw) { Text(LocalizedStringKey(preset.labelKey)) }\n'
                                  '                        else { Text(verbatim: raw) }\n'
                                  '                    } else { Text("templateMetadata.choose") }\n'
                                  '                } label: { Text("templateAuthor.field.usageLocation") }\n'
                                  '                    .frame(maxWidth: .infinity, minHeight: '
                                  '44).contentShape(Rectangle())\n'
                                  '            }\n'
                                  '            .buttonStyle(.borderless)\n'
                                  '            .disabled(!model.canEdit || model.busy || '
                                  'model.coordinator.review != nil)\n'
                                  '            .accessibilityIdentifier("templateVenue.open")\n'
                                  '        }\n'
                                  '        .sheet(item: $presented) { presentation in\n'
                                  '            NavigationStack { TemplateAuthoringVenueSelector(model: '
                                  'model).id(presentation.id) }\n'
                                  '        }\n'
                                  '    }\n'
                                  '}\n'
                                  '\n'
                                  '@MainActor private struct TemplateAuthoringVenueSelector: View {\n'
                                  '    @Environment(\\.dismiss) private var dismiss\n'
                                  '    @ObservedObject private var model: TemplateAuthoringModel\n'
                                  '    @StateObject private var editor: TemplateAuthoringVenueEditor\n'
                                  '    init(model: TemplateAuthoringModel) {\n'
                                  '        self.model = model; _editor = StateObject(wrappedValue: '
                                  '.init(model: model))\n'
                                  '    }\n'
                                  '    var body: some View {\n'
                                  '        List {\n'
                                  '            if editor.canRead {\n'
                                  '                Section("templateMetadata.saved") {\n'
                                  '                    if let raw = editor.savedRawValue { Text(verbatim: '
                                  'raw).accessibilityIdentifier("templateVenue.savedRaw") }\n'
                                  '                    else { Text("templateMetadata.unset") }\n'
                                  '                    if editor.hasHistoricalValue { '
                                  'Text("templateVenue.historical").font(.caption).foregroundStyle(.secondary) '
                                  '}\n'
                                  '                }\n'
                                  '                Section {\n'
                                  '                    ForEach(TemplateVenuePreset.allCases) { preset in\n'
                                  '                        Button { if editor.select(preset) { dismiss() } } '
                                  'label: {\n'
                                  '                            HStack {\n'
                                  '                                '
                                  'Text(LocalizedStringKey(preset.labelKey))\n'
                                  '                                Spacer()\n'
