             {'path': 'Core/RoamExperienceMath.swift',
              'status': 'M',
              'before_sha256': '65f5ef1e0f0161c5875f6e962790e2690ef9de210da7cb75b7a72c3cda3b8a6b',
              'before_blob': '5acbc3090a1c1a4ca8d11d07ead2ac974b0036e6',
              'after_sha256': '02acd81d49d370748da8c780447b771bc7913e8813a9c537e04509b233e266f1',
              'after_blob': '94e0b1fcac0edcc7e2f4c300747e812deb3f5795',
              'hunks': [{'before': '        generation = UUID(); phase = .completed; visibleSegments = nil\n'
                                   '    }\n'
                                   '}\n',
                         'after': '        generation = UUID(); phase = .completed; visibleSegments = nil\n'
                                  '    }\n'
                                  '}\n'
                                  '\n'
                                  '/// P128 local share projection only. Historical records remain '
                                  'unchanged.\n'
                                  '/// Saved tracks are simplified, so clip by polyline length rather than '
                                  'sample count.\n'
                                  'public enum RoamShareRoutePrivacy {\n'
                                  '    public static let endpointFraction = 0.1\n'
                                  '\n'
                                  '    public static func clippedTrack(_ track: [RoamHistoryPoint]) -> '
                                  '[RoamHistoryPoint] {\n'
                                  '        guard track.count >= 2 else { return [] }\n'
                                  '        var lengths: [Double] = []\n'
                                  '        for index in 1..<track.count {\n'
                                  '            let a = track[index - 1], b = track[index]\n'
                                  '            // A schematic cannot safely interpolate a longitude wrap. '
                                  'Hide it rather than\n'
                                  '            // drawing a trans-world segment or returning the original '
                                  'endpoints.\n'
                                  '            guard abs(b.lng - a.lng) <= 180 else { return [] }\n'
                                  '            '
                                  'lengths.append(RoamExperienceMath.distanceMeters(a.coordinate, '
                                  'b.coordinate))\n'
                                  '        }\n'
                                  '        let total = lengths.reduce(0, +)\n'
                                  '        guard total.isFinite, total > 0 else { return [] }\n'
                                  '        let start = total * endpointFraction, end = total - start\n'
                                  '        var travelled = 0.0\n'
                                  '        var result: [RoamHistoryPoint] = []\n'
                                  '        for index in 1..<track.count {\n'
                                  '            let length = lengths[index - 1], next = travelled + length\n'
                                  '            if length > 0, next > start, travelled < end {\n'
                                  '                let a = track[index - 1], b = track[index]\n'
                                  '                func interpolate(_ distance: Double) -> RoamHistoryPoint? '
                                  '{\n'
                                  '                    let fraction = min(1, max(0, (distance - travelled) / '
                                  'length))\n'
                                  '                    guard let coordinate = RoamCoordinate(\n'
                                  '                        latitude: a.lat + (b.lat - a.lat) * fraction,\n'
                                  '                        longitude: a.lng + (b.lng - a.lng) * fraction\n'
                                  '                    ) else { return nil }\n'
                                  '                    return RoamHistoryPoint(coordinate: coordinate)\n'
                                  '                }\n'
                                  '                if result.isEmpty {\n'
                                  '                    guard let point = interpolate(max(start, travelled)) '
                                  'else { return [] }\n'
                                  '                    result.append(point)\n'
                                  '                }\n'
                                  '                guard let point = interpolate(min(end, next)) else { '
                                  'return [] }\n'
                                  '                result.append(point)\n'
                                  '            }\n'
                                  '            travelled = next\n'
                                  '            if travelled >= end { break }\n'
                                  '        }\n'
                                  '        guard result.count >= 2 else { return [] }\n'
                                  '        // Interpolation may round back to an original endpoint for '
                                  'adjacent Doubles.\n'
                                  '        // A nominal 10% calculation is not evidence that the exported '
                                  'endpoint moved.\n'
                                  '        let startInset = '
                                  'RoamExperienceMath.distanceMeters(track[0].coordinate, '
                                  'result[0].coordinate)\n'
                                  '        let endInset = '
                                  'RoamExperienceMath.distanceMeters(track[track.count - 1].coordinate, '
                                  'result[result.count - 1].coordinate)\n'
                                  '        guard startInset.isFinite, startInset > 0, endInset.isFinite, '
                                  'endInset > 0 else { return [] }\n'
                                  '        var retainedLength = 0.0\n'
                                  '        for index in 1..<result.count {\n'
                                  '            retainedLength += '
                                  'RoamExperienceMath.distanceMeters(result[index - 1].coordinate, '
                                  'result[index].coordinate)\n'
                                  '        }\n'
                                  '        guard retainedLength.isFinite, retainedLength > 0 else { return '
                                  '[] }\n'
                                  '        return result\n'
                                  '    }\n'
                                  '\n'
                                  '    public static func sketch(for record: RoamHistoryRecord) -> '
                                  'RoamRouteSketch {\n'
                                  '        // POIs could independently reveal the removed home/work '
                                  'endpoint. Do not export them.\n'
                                  '        RoamRouteSketch(track: clippedTrack(record.track), places: [])\n'
                                  '    }\n'
                                  '}\n'}]},
